#!/bin/bash
# Claude Code notification dispatcher.
#
# Invoked by Notification / Stop / SubagentStop hooks in ~/.claude/settings.json.
# Reads the Claude Code hook payload from stdin (JSON) and fires a native macOS
# notification via terminal-notifier. Clicking the notification runs
# ghostty-focus.sh to select the originating tmux pane and bring Ghostty forward.
#
# Requires paths.env (generated by setup-notifications.sh) for absolute paths
# to jq / tmux / terminal-notifier — hooks run with a minimal PATH, so rc-file
# exports aren't available here.

set -u

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PATHS_ENV="$SCRIPT_DIR/paths.env"

if [[ ! -f "$PATHS_ENV" ]]; then
  # Fail visibly on the terminal even if notifications are broken.
  echo "notify.sh: missing $PATHS_ENV — run setup-notifications.sh" >&2
  exit 1
fi
# shellcheck source=/dev/null
source "$PATHS_ENV"

INPUT=$(cat)

# Defensive defaults: the Notification payload schema isn't fully documented,
# so every jq expression falls back to empty string rather than null-crashing.
EVENT=$(printf '%s' "$INPUT" | "$JQ" -r '.hook_event_name // ""')
MESSAGE=$(printf '%s' "$INPUT" | "$JQ" -r '.message // ""')
TITLE=$(printf '%s' "$INPUT" | "$JQ" -r '.title // ""')
CWD=$(printf '%s' "$INPUT" | "$JQ" -r '.cwd // ""')
SESSION_ID=$(printf '%s' "$INPUT" | "$JQ" -r '.session_id // ""')

case "$EVENT" in
  Stop)
    : "${MESSAGE:=Task completed}"
    : "${TITLE:=Claude Code}"
    SOUND="Hero"
    ;;
  SubagentStop)
    : "${MESSAGE:=Subagent done}"
    : "${TITLE:=Claude Code}"
    SOUND="Tink"
    ;;
  Notification|*)
    : "${MESSAGE:=Needs attention}"
    : "${TITLE:=Claude Code}"
    SOUND="Glass"
    ;;
esac

# Append project name to title so concurrent sessions are distinguishable.
if [[ -n "$CWD" ]]; then
  PROJECT=$(basename "$CWD")
  TITLE="$TITLE — $PROJECT"
fi

# Build terminal-notifier args incrementally. Click-to-focus is opt-in:
# only attach -execute when we actually have a tmux target.
ARGS=(
  -title "$TITLE"
  -message "$MESSAGE"
  -sound "$SOUND"
)

if [[ -n "$SESSION_ID" ]]; then
  ARGS+=(-group "$SESSION_ID")
fi

if [[ -n "${TMUX:-}" ]] && command -v "$TMUX_BIN" >/dev/null 2>&1; then
  TMUX_TARGET=$("$TMUX_BIN" display-message -p '#S:#I.#P' 2>/dev/null || true)
  if [[ -n "$TMUX_TARGET" ]]; then
    ARGS+=(-execute "$SCRIPT_DIR/ghostty-focus.sh $TMUX_TARGET")
  fi
fi

"$NOTIFIER" "${ARGS[@]}" >/dev/null 2>&1 || true
